  "config.details.diagnostics": "\u529F\u80FD\uFF1A\u5728\u4FA7\u680F\u663E\u793A\u62D6\u62FD\u76EE\u6807 HUD\uFF0C\u5E76\u628A\u5206\u7EC4\u64CD\u4F5C\u3001\u62D6\u62FD\u3001\u6E32\u67D3\u548C\u4FEE\u8BA2\u53F7\u5199\u5165\u672C\u5730 NDJSON \u8BCA\u65AD\u6587\u4EF6\u3002\n\u4F55\u65F6\u5F00\u542F\uFF1A\u4EC5\u5728\u6392\u67E5\u62D6\u62FD\u3001\u951A\u70B9\u3001\u865A\u62DF\u5217\u8868\u6216\u5E03\u5C40\u95EE\u9898\u65F6\u4E34\u65F6\u5F00\u542F\uFF1B\u6B63\u5E38\u4F7F\u7528\u4FDD\u6301\u5173\u95ED\u3002\n\u5B89\u5168\u98CE\u9669\uFF1A\u8BCA\u65AD\u6587\u4EF6\u4FDD\u5B58\u5728\u672C\u673A DSH storages \u76EE\u5F55\uFF0C\u53EF\u80FD\u5305\u542B\u5206\u7EC4 ID\u3001\u4F1A\u8BDD ID\u3001\u8DEF\u5F84\u3001\u89C6\u53E3\u5C3A\u5BF8\u548C\u64CD\u4F5C\u5E8F\u5217\uFF1B\u9ED8\u8BA4\u4E0D\u8BB0\u5F55\u4F1A\u8BDD\u6B63\u6587\uFF0C\u4F46\u672C\u5730\u5176\u4ED6\u7A0B\u5E8F\u4ECD\u53EF\u80FD\u8BFB\u53D6\u8BE5\u6587\u4EF6\u3002\n\u5176\u4ED6\u5F71\u54CD\uFF1A\u4F1A\u589E\u52A0\u5C11\u91CF\u5185\u5B58\u3001CPU \u548C\u78C1\u76D8\u5199\u5165\uFF1B\u5173\u95ED\u540E\u505C\u6B62\u5199\u5165\uFF0C\u4F46\u5DF2\u6709\u8BCA\u65AD\u6587\u4EF6\u4E0D\u4F1A\u81EA\u52A8\u5220\u9664\u3002",
  "config.details.debugProbe": "\u529F\u80FD\uFF1A\u4E3A\u5F39\u7A97\u5E03\u5C40\u8C03\u8BD5\u5F00\u653E\u672C\u5730 .debug.ndjson \u63A2\u9488\uFF0C\u8BB0\u5F55\u5F39\u7A97\u5C3A\u5BF8\u3001\u4F4D\u7F6E\u548C\u5E03\u5C40\u8BA1\u7B97\u3002\n\u4F55\u65F6\u5F00\u542F\uFF1A\u53EA\u5728\u5F00\u53D1\u6216\u590D\u73B0\u5F39\u7A97\u51E0\u4F55\u3001\u62D6\u62FD\u3001\u7F29\u653E\u95EE\u9898\u65F6\u5F00\u542F\uFF1B\u751F\u4EA7\u73AF\u5883\u4E0D\u8981\u5F00\u542F\u3002\n\u5B89\u5168\u98CE\u9669\uFF1A\u4F1A\u66B4\u9732\u672C\u5730\u8C03\u8BD5\u7AEF\u70B9\u548C\u5E03\u5C40\u6570\u636E\uFF0C\u53EF\u80FD\u5305\u542B\u4F1A\u8BDD/\u5206\u7EC4 ID \u4E0E\u7A97\u53E3\u5C3A\u5BF8\uFF1B\u4E0D\u8981\u5728\u4E0D\u53EF\u4FE1\u73AF\u5883\u957F\u671F\u5F00\u542F\u3002\n\u5176\u4ED6\u5F71\u54CD\uFF1A\u589E\u52A0\u8C03\u8BD5\u6587\u4EF6\u5199\u5165\u548C\u8BF7\u6C42\uFF1B\u5173\u95ED\u540E\u8C03\u8BD5\u7AEF\u70B9\u505C\u7528\u3002",
  "config.details.controlApi": "\u529F\u80FD\uFF1A\u542F\u7528\u539F\u751F session_grove_control \u5DE5\u5177\uFF0C\u5E76\u4FDD\u7559\u6D4F\u89C8\u5668/\u8C03\u8BD5\u7528 HTTP \u63A7\u5236\u8DEF\u7531\uFF1B\u53EF\u8BFB\u53D6\u5206\u7EC4\u72B6\u6001\u3001\u9884\u89C8\u548C\u63D0\u4EA4\u5206\u7EC4\u64CD\u4F5C\u3002\n\u4F55\u65F6\u5F00\u542F\uFF1A\u53EA\u6709\u5F53\u4F60\u5E0C\u671B AI \u6216\u53D7\u4FE1\u4EFB\u7684\u672C\u5730\u81EA\u52A8\u5316\u7BA1\u7406\u5206\u7EC4\u65F6\u624D\u5F00\u542F\uFF1B\u666E\u901A\u624B\u52A8\u4F7F\u7528\u4FDD\u6301\u5173\u95ED\u3002\n\u5B89\u5168\u98CE\u9669\uFF1A\u8C03\u7528\u65B9\u53EF\u679A\u4E3E\u548C\u4FEE\u6539\u5206\u7EC4\u3001\u8BFB\u5199\u4F1A\u8BDD\u7684\u5206\u7EC4\u5F52\u5C5E\uFF1B\u82E5\u6A21\u578B\u88AB\u63D0\u793A\u6CE8\u5165\u6216\u672C\u5730\u8FDB\u7A0B\u88AB\u5192\u7528\uFF0C\u53EF\u80FD\u6267\u884C\u975E\u9884\u671F\u6539\u7EC4\u3002\u539F\u751F\u5DE5\u5177\u5728 Host \u8FDB\u7A0B\u5185\u8FD0\u884C\uFF0C\u4E0D\u7ECF\u8FC7\u6D4F\u89C8\u5668 fence\uFF1BHTTP \u8DEF\u7531\u4ECD\u53D7\u6D4F\u89C8\u5668\u4F1A\u8BDD fence \u4FDD\u62A4\u3002\u8BF7\u53EA\u8BA9\u53EF\u4FE1 AI/\u672C\u5730\u8C03\u7528\u65B9\u4F7F\u7528\u3002\n\u5176\u4ED6\u5F71\u54CD\uFF1A\u4F1A\u751F\u6210\u5E76\u7EF4\u62A4\u672C\u5730\u63A7\u5236 token\uFF0C\u5E76\u6CE8\u518C\u539F\u751F\u5DE5\u5177\uFF1B\u5173\u95ED\u540E\u5DE5\u5177\u548C\u8DEF\u7531\u7ACB\u5373\u62D2\u7EDD\u64CD\u4F5C\uFF0C\u4F46\u5DF2\u6709\u5206\u7EC4\u6570\u636E\u4E0D\u4F1A\u56DE\u6EDA\u3002",
  "config.details.controlDestructive": "\u529F\u80FD\uFF1A\u5141\u8BB8 AI \u63A7\u5236\u63A5\u53E3\u5220\u9664\u5206\u7EC4\uFF1B\u5220\u9664\u975E\u7A7A\u5206\u7EC4\u65F6\u5FC5\u987B\u5148\u628A\u4F1A\u8BDD\u548C\u5B50\u7EC4\u8F6C\u79FB\u5230\u76EE\u6807\u5206\u7EC4\uFF0C\u4E0D\u4F1A\u5220\u9664\u6216\u5F52\u6863\u4F1A\u8BDD\u672C\u8EAB\u3002\n\u4F55\u65F6\u5F00\u542F\uFF1A\u4EC5\u5728\u660E\u786E\u8981\u6C42 AI \u6267\u884C\u5206\u7EC4\u5220\u9664\u65F6\u4E34\u65F6\u5F00\u542F\uFF1B\u6B63\u5E38\u4F7F\u7528\u4FDD\u6301\u5173\u95ED\u3002\n\u5B89\u5168\u98CE\u9669\uFF1A\u8FD9\u662F\u9AD8\u6743\u9650\u64CD\u4F5C\uFF1B\u4E00\u6B21\u9519\u8BEF\u8C03\u7528\u53EF\u80FD\u6C38\u4E45\u79FB\u9664\u5206\u7EC4\u5C42\u7EA7\u5E76\u6539\u53D8\u4F1A\u8BDD\u7684\u5206\u7EC4\u5F52\u5C5E\u3002\u5220\u9664\u524D\u5FC5\u987B\u786E\u8BA4\u76EE\u6807\u548C\u76EE\u6807\u5206\u7EC4\uFF0C\u5EFA\u8BAE\u4FDD\u7559\u5206\u7EC4\u6587\u4EF6\u5907\u4EFD\u3002\n\u5176\u4ED6\u5F71\u54CD\uFF1AUI \u4E0D\u63D0\u4F9B\u64A4\u9500\uFF1B\u6062\u590D\u901A\u5E38\u9700\u8981\u4ECE dsh-session-grove.json \u5907\u4EFD\u91CD\u5EFA\u5206\u7EC4\uFF0C\u56E0\u6B64\u4E0D\u8981\u628A\u6B64\u5F00\u5173\u5F53\u4F5C\u65E5\u5E38\u529F\u80FD\u3002",
  "config.details.controlSessions": "\u529F\u80FD\uFF1A\u5141\u8BB8 AI/\u5DE5\u5177\u8BFB\u53D6\u4F1A\u8BDD\u6807\u9898\u3001\u91CD\u547D\u540D\u4F1A\u8BDD\u3001\u5F52\u6863\u6216\u6062\u590D\u4F1A\u8BDD\u3002\n\u4F55\u65F6\u5F00\u542F\uFF1A\u53EA\u6709\u5F53\u4F60\u5E0C\u671B AI \u7BA1\u7406\u4F1A\u8BDD\u6807\u9898\u6216\u5F52\u6863\u72B6\u6001\u65F6\u624D\u5F00\u542F\uFF1B\u4EC5\u7BA1\u7406\u5206\u7EC4\u65F6\u4FDD\u6301\u5173\u95ED\u3002\n\u5B89\u5168\u98CE\u9669\uFF1A\u6539\u540D\u4F1A\u6539\u53D8\u4F1A\u8BDD\u5728\u5217\u8868\u4E2D\u7684\u663E\u793A\uFF1B\u5F52\u6863\u8FD0\u884C\u4E2D\u7684\u4F1A\u8BDD\u53EF\u80FD\u505C\u6B62\u6B63\u5728\u8FDB\u884C\u7684\u6D3B\u52A8\uFF08\u9700\u8981\u663E\u5F0F stopActivity\uFF09\u3002\u5F52\u6863\u53EF\u9006\uFF0C\u4F46\u9519\u8BEF\u6539\u540D/\u5F52\u6863\u4F1A\u5F71\u54CD\u4F1A\u8BDD\u8BC6\u522B\u548C\u53EF\u89C1\u6027\u3002\u5FC5\u987B\u7528 sessionId \u660E\u786E\u6307\u5B9A\u76EE\u6807\uFF0C\u4E0D\u8981\u731C\u6D4B\u3002\n\u5176\u4ED6\u5F71\u54CD\uFF1A\u6807\u9898\u548C\u5F52\u6863\u5C5E\u4E8E DSH \u6838\u5FC3\u4F1A\u8BDD\u72B6\u6001\uFF0C\u4E0D\u5C5E\u4E8E\u5206\u7EC4\u6587\u6863\uFF1B\u4E0D\u80FD\u4E0E\u5206\u7EC4\u5F52\u5C5E\u64CD\u4F5C\u7EC4\u6210\u5355\u4E00\u4E8B\u52A1\u3002",
