  "dialog.deleteMoveBody": "\uC774 \uADF8\uB8F9\uC5D0\uB294 \uC138\uC158 {sessions}\uAC1C\uC640 \uD558\uC704 \uADF8\uB8F9 {groups}\uAC1C\uAC00 \uC788\uC2B5\uB2C8\uB2E4. \uADF8\uB8F9\uC744 \uC0AD\uC81C\uD558\uAE30 \uC804\uC5D0 \uC774\uB4E4\uC744 \uC5B4\uB514\uB85C \uB2E4\uC2DC \uBC30\uC815\uD560\uC9C0 \uC120\uD0DD\uD558\uC138\uC694. \uC138\uC158\uC740 \uC0AD\uC81C\uB418\uAC70\uB098 \uBCF4\uAD00\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
