  "dialog.archiveRunning": "\uC138\uC158\uC774 \uC2E4\uD589 \uC911\uC785\uB2C8\uB2E4",
  "dialog.archiveRunningBody": "\uC774 \uC138\uC158\uC5D0\uB294 \uC9C4\uD589 \uC911\uC778 \uC791\uC5C5({families})\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uBCF4\uAD00\uD558\uBA74 \uD574\uB2F9 \uC791\uC5C5\uC774 \uC911\uC9C0\uB429\uB2C8\uB2E4.",
