  "dialog.noWorkspace": "\uC0AC\uC6A9\uD560 \uC218 \uC788\uB294 \uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uBA3C\uC800 \uAE30\uBCF8 \uC0AC\uC774\uB4DC\uBC14\uC5D0\uC11C \uC6CC\uD06C\uC2A4\uD398\uC774\uC2A4\uB97C \uCD94\uAC00\uD558\uC138\uC694.",
