  "config.controlApi": "KI-Steuerungs-API",
  "config.controlApiHint": "Aktiviert die Routen state / resolve / plan / apply sowie die Sitzungsoperationen.",
  "config.controlDestructive": "Destruktive Vorg\xE4nge zulassen",
  "config.controlDestructiveHint": "Erlaubt der KI-Steuerungs-API, Gruppen zu l\xF6schen.",
