  "config.controlApi": "API sterowania przez AI",
  "config.controlApiHint": "W\u0142\u0105cza trasy state / resolve / plan / apply oraz trasy operacji na sesjach.",
  "config.controlDestructive": "Zezwalaj na operacje destrukcyjne",
  "config.controlDestructiveHint": "Pozwala API sterowania przez AI usuwa\u0107 grupy.",
