  "config.controlSessionsHint": "Cho ph\xE9p \u0111\u1ED5i t\xEAn phi\xEAn v\xE0 thay \u0111\u1ED5i tr\u1EA1ng th\xE1i l\u01B0u tr\u1EEF.",
  "session.archived": "\u0110\xE3 l\u01B0u tr\u1EEF",
  "banner.registration-failed": "\u0110\u0103ng k\xFD thanh b\xEAn nh\xF3m t\u1EF1 do th\u1EA5t b\u1EA1i",
  "config.details.diagnostics": "Ch\u1EE9c n\u0103ng: hi\u1EC3n th\u1ECB HUD \u0111i\u1EC3m th\u1EA3 v\xE0 ghi c\xE1c thao t\xE1c nh\xF3m, thao t\xE1c k\xE9o th\u1EA3, l\u1EA7n k\u1EBFt xu\u1EA5t c\xF9ng b\u1EA3n s\u1EEDa \u0111\u1ED5i v\xE0o b\u1EA3n ghi NDJSON c\u1EE5c b\u1ED9.\nKhi n\xE0o n\xEAn b\u1EADt: ch\u1EC9 b\u1EADt t\u1EA1m th\u1EDDi khi ch\u1EA9n \u0111o\xE1n \u0111i\u1EC3m th\u1EA3, \u0111i\u1EC3m neo, \u1EA3o h\xF3a ho\u1EB7c b\u1ED1 c\u1EE5c. Gi\u1EEF t\u1EAFt trong s\u1EED d\u1EE5ng th\xF4ng th\u01B0\u1EDDng.\nB\u1EA3o m\u1EADt: b\u1EA3n ghi n\u1EB1m trong th\u01B0 m\u1EE5c storages c\u1EE5c b\u1ED9 c\u1EE7a DSH v\xE0 c\xF3 th\u1EC3 ch\u1EE9a ID nh\xF3m, ID phi\xEAn, \u0111\u01B0\u1EDDng d\u1EABn, k\xEDch th\u01B0\u1EDBc khung nh\xECn v\xE0 tr\xECnh t\u1EF1 thao t\xE1c. Theo m\u1EB7c \u0111\u1ECBnh, n\u1ED9i dung tin nh\u1EAFn c\u1EE7a phi\xEAn kh\xF4ng \u0111\u01B0\u1EE3c ghi l\u1EA1i, nh\u01B0ng c\xE1c ch\u01B0\u01A1ng tr\xECnh c\u1EE5c b\u1ED9 kh\xE1c c\xF3 th\u1EC3 \u0111\u1ECDc t\u1EC7p n\xE0y.\nT\xE1c \u0111\u1ED9ng kh\xE1c: t\u1ED1n th\xEAm m\u1ED9t \xEDt b\u1ED9 nh\u1EDB, CPU v\xE0 l\u01B0\u1EE3t ghi \u0111\u0129a. T\u1EAFt \u0111i s\u1EBD d\u1EEBng vi\u1EC7c ghi m\u1EDBi nh\u01B0ng kh\xF4ng x\xF3a c\xE1c t\u1EC7p b\u1EA3n ghi hi\u1EC7n c\xF3.",
  "config.details.debugProbe": "Ch\u1EE9c n\u0103ng: b\u1EADt b\u1ED9 d\xF2 .debug.ndjson c\u1EE5c b\u1ED9 v\xE0 ghi k\xEDch th\u01B0\u1EDBc, v\u1ECB tr\xED h\u1ED9p tho\u1EA1i c\xF9ng c\xE1c ph\xE9p t\xEDnh b\u1ED1 c\u1EE5c.\nKhi n\xE0o n\xEAn b\u1EADt: ch\u1EC9 b\u1EADt trong m\xF4i tr\u01B0\u1EDDng ph\xE1t tri\u1EC3n ho\u1EB7c khi \u0111ang t\xE1i hi\u1EC7n l\u1ED7i h\xECnh h\u1ECDc h\u1ED9p tho\u1EA1i, k\xE9o th\u1EA3 hay thay \u0111\u1ED5i k\xEDch th\u01B0\u1EDBc. Gi\u1EEF t\u1EAFt trong m\xF4i tr\u01B0\u1EDDng v\u1EADn h\xE0nh.\nB\u1EA3o m\u1EADt: m\u1EDF ra m\u1ED9t \u0111i\u1EC3m cu\u1ED1i g\u1EE1 l\u1ED7i c\u1EE5c b\u1ED9 c\xF9ng d\u1EEF li\u1EC7u b\u1ED1 c\u1EE5c c\xF3 th\u1EC3 ch\u1EE9a ID phi\xEAn/nh\xF3m v\xE0 k\xEDch th\u01B0\u1EDBc c\u1EEDa s\u1ED5. Kh\xF4ng \u0111\u1EC3 b\u1EADt trong m\xF4i tr\u01B0\u1EDDng kh\xF4ng tin c\u1EADy.\nT\xE1c \u0111\u1ED9ng kh\xE1c: t\u0103ng l\u01B0\u1EE3t ghi t\u1EC7p g\u1EE1 l\u1ED7i v\xE0 y\xEAu c\u1EA7u. T\u1EAFt \u0111i s\u1EBD \u0111\xF3ng \u0111i\u1EC3m cu\u1ED1i n\xE0y.",
  "config.details.controlApi": "Ch\u1EE9c n\u0103ng: b\u1EADt c\xF4ng c\u1EE5 g\u1ED1c session_grove_control v\xE0 gi\u1EEF c\xE1c tuy\u1EBFn HTTP \u0111i\u1EC1u khi\u1EC3n d\xE0nh cho tr\xECnh duy\u1EC7t/g\u1EE1 l\u1ED7i \u0111\u1EC3 \u0111\u1ECDc tr\u1EA1ng th\xE1i nh\xF3m, l\u1EADp k\u1EBF ho\u1EA1ch v\xE0 \xE1p d\u1EE5ng thay \u0111\u1ED5i nh\xF3m.\nKhi n\xE0o n\xEAn b\u1EADt: ch\u1EC9 khi b\u1EA1n mu\u1ED1n AI ho\u1EB7c t\u1EF1 \u0111\u1ED9ng h\xF3a c\u1EE5c b\u1ED9 \u0111\xE1ng tin c\u1EADy qu\u1EA3n l\xFD nh\xF3m. Gi\u1EEF t\u1EAFt cho thao t\xE1c th\u1EE7 c\xF4ng th\xF4ng th\u01B0\u1EDDng.\nB\u1EA3o m\u1EADt: ngu\u1ED3n g\u1ECDi c\xF3 th\u1EC3 li\u1EC7t k\xEA v\xE0 thay \u0111\u1ED5i nh\xF3m c\xF9ng c\xE1ch g\xE1n nh\xF3m. Vi\u1EC7c ch\xE8n ch\u1EC9 d\u1EABn \u0111\u1ED9c h\u1EA1i v\xE0o n\u1ED9i dung \u0111\u1EA7u v\xE0o ho\u1EB7c m\u1ED9t ti\u1EBFn tr\xECnh c\u1EE5c b\u1ED9 b\u1ECB chi\u1EBFm quy\u1EC1n c\xF3 th\u1EC3 g\xE2y ra nh\u1EEFng thay \u0111\u1ED5i ngo\xE0i \xFD mu\u1ED1n. C\xF4ng c\u1EE5 g\u1ED1c ch\u1EA1y trong c\xF9ng ti\u1EBFn tr\xECnh v\xE0 kh\xF4ng v\u01B0\u1EE3t qua ranh gi\u1EDBi b\u1EA3o v\u1EC7 c\u1EE7a tr\xECnh duy\u1EC7t; c\xE1c tuy\u1EBFn HTTP v\u1EABn n\u1EB1m sau ranh gi\u1EDBi phi\xEAn tr\xECnh duy\u1EC7t. Ch\u1EC9 cho ph\xE9p nh\u1EEFng ngu\u1ED3n g\u1ECDi AI/c\u1EE5c b\u1ED9 \u0111\xE1ng tin c\u1EADy.\nT\xE1c \u0111\u1ED9ng kh\xE1c: t\u1EA1o v\xE0 duy tr\xEC m\u1ED9t m\xE3 th\xF4ng b\xE1o \u0111i\u1EC1u khi\u1EC3n c\u1EE5c b\u1ED9, \u0111\u1ED3ng th\u1EDDi \u0111\u0103ng k\xFD c\xF4ng c\u1EE5 g\u1ED1c. T\u1EAFt \u0111i s\u1EBD khi\u1EBFn c\xF4ng c\u1EE5 v\xE0 c\xE1c tuy\u1EBFn t\u1EEB ch\u1ED1i thao t\xE1c ngay l\u1EADp t\u1EE9c, nh\u01B0ng kh\xF4ng ho\xE0n nguy\xEAn d\u1EEF li\u1EC7u nh\xF3m hi\u1EC7n c\xF3.",
  "config.details.controlDestructive": "Ch\u1EE9c n\u0103ng: cho ph\xE9p b\u1EC1 m\u1EB7t \u0111i\u1EC1u khi\u1EC3n AI x\xF3a nh\xF3m. Mu\u1ED1n x\xF3a m\u1ED9t nh\xF3m kh\xF4ng tr\u1ED1ng, ph\u1EA3i g\xE1n l\u1EA1i c\xE1c phi\xEAn v\xE0 nh\xF3m con c\u1EE7a nh\xF3m \u0111\xF3 sang m\u1ED9t nh\xF3m \u0111\xEDch; b\u1EA3n th\xE2n c\xE1c phi\xEAn kh\xF4ng bao gi\u1EDD b\u1ECB x\xF3a hay l\u01B0u tr\u1EEF.\nKhi n\xE0o n\xEAn b\u1EADt: ch\u1EC9 b\u1EADt t\u1EA1m th\u1EDDi khi b\u1EA1n th\u1EF1c s\u1EF1 mu\u1ED1n AI x\xF3a m\u1ED9t nh\xF3m. Gi\u1EEF t\u1EAFt trong s\u1EED d\u1EE5ng th\xF4ng th\u01B0\u1EDDng.\nB\u1EA3o m\u1EADt: \u0111\xE2y l\xE0 thao t\xE1c c\xF3 quy\u1EC1n cao. M\u1ED9t l\u1EA7n g\u1ECDi nh\u1EA7m c\xF3 th\u1EC3 x\xF3a v\u0129nh vi\u1EC5n c\u1EA3 c\xE2y nh\xF3m v\xE0 thay \u0111\u1ED5i c\xE1ch g\xE1n nh\xF3m. H\xE3y x\xE1c nh\u1EADn nh\xF3m m\u1EE5c ti\xEAu v\xE0 nh\xF3m \u0111\xEDch, \u0111\u1ED3ng th\u1EDDi sao l\u01B0u t\u1EC7p nh\xF3m.\nT\xE1c \u0111\u1ED9ng kh\xE1c: giao di\u1EC7n kh\xF4ng ho\xE0n t\xE1c \u0111\u01B0\u1EE3c vi\u1EC7c x\xF3a; mu\u1ED1n kh\xF4i ph\u1EE5c th\u01B0\u1EDDng ph\u1EA3i d\u1EF1ng l\u1EA1i t\u1EEB b\u1EA3n sao l\u01B0u dsh-session-grove.json. \u0110\u1EEBng coi \u0111\xE2y l\xE0 thi\u1EBFt l\u1EADp d\xF9ng h\u1EB1ng ng\xE0y.",
  "config.details.controlSessions": "Ch\u1EE9c n\u0103ng: cho ph\xE9p AI/c\xF4ng c\u1EE5 xem ti\xEAu \u0111\u1EC1 phi\xEAn, \u0111\u1ED5i t\xEAn phi\xEAn v\xE0 l\u01B0u tr\u1EEF ho\u1EB7c kh\xF4i ph\u1EE5c phi\xEAn.\nKhi n\xE0o n\xEAn b\u1EADt: ch\u1EC9 b\u1EADt khi b\u1EA1n mu\u1ED1n AI qu\u1EA3n l\xFD ti\xEAu \u0111\u1EC1 ho\u1EB7c tr\u1EA1ng th\xE1i l\u01B0u tr\u1EEF c\u1EE7a phi\xEAn. Gi\u1EEF t\u1EAFt n\u1EBFu ch\u1EC9 qu\u1EA3n l\xFD nh\xF3m.\nB\u1EA3o m\u1EADt: \u0111\u1ED5i t\xEAn s\u1EBD thay \u0111\u1ED5i c\xE1ch phi\xEAn hi\u1EC3n th\u1ECB trong danh s\xE1ch; l\u01B0u tr\u1EEF m\u1ED9t phi\xEAn \u0111ang ch\u1EA1y c\xF3 th\u1EC3 d\u1EEBng c\xF4ng vi\u1EC7c \u0111ang di\u1EC5n ra (c\u1EA7n stopActivity r\xF5 r\xE0ng). L\u01B0u tr\u1EEF c\xF3 th\u1EC3 \u0111\u1EA3o ng\u01B0\u1EE3c, nh\u01B0ng \u0111\u1ED5i t\xEAn ho\u1EB7c l\u01B0u tr\u1EEF sai c\xF3 th\u1EC3 \u1EA3nh h\u01B0\u1EDFng \u0111\u1EBFn vi\u1EC7c nh\u1EADn di\u1EC7n v\xE0 kh\u1EA3 n\u0103ng hi\u1EC3n th\u1ECB. Lu\xF4n d\xF9ng sessionId r\xF5 r\xE0ng; kh\xF4ng \u0111o\xE1n.\nT\xE1c \u0111\u1ED9ng kh\xE1c: ti\xEAu \u0111\u1EC1 v\xE0 tr\u1EA1ng th\xE1i l\u01B0u tr\u1EEF thu\u1ED9c tr\u1EA1ng th\xE1i phi\xEAn c\u1EE7a l\xF5i DSH, kh\xF4ng thu\u1ED9c t\xE0i li\u1EC7u nh\xF3m, n\xEAn kh\xF4ng th\u1EC3 g\u1ED9p chung m\u1ED9t giao d\u1ECBch v\u1EDBi vi\u1EC7c g\xE1n nh\xF3m.",
